export const musicRecipes:MusicRecipe[] = seeds.map(r=>({...r,
  exampleStyle:`${r.genre}, ${r.bpm} BPM. ${r.groove}. ${r.palette.map(([,role])=>role).join('; ')}. ${r.production}. ${r.arc}.`,
  sourceIds:['songwriting','cookbook','suno-exclude'], evidence:'working-hypothesis',
}));
export function findMusicRecipe(id?:string){return musicRecipes.find(r=>r.id===id);}
const folded=(s:string)=>s.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase();
export function suggestMusicRecipes(text:string,limit=2){
  const normalized=` ${folded(text).replace(/[^\p{L}\p{N}&]+/gu,' ')} `;
  return musicRecipes.map(recipe=>({recipe,score:Math.max(0,...recipe.tags.map(tag=>normalized.includes(` ${folded(tag).replace(/[^\p{L}\p{N}&]+/gu,' ')} `)?tag.length:0))}))
    .filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,limit).map(x=>x.recipe);
}
export function applyMusicRecipe(brief:Brief,recipe:MusicRecipe,mode:'guide'|'preset'):Brief {
  if(mode==='guide')return normalizeBrief({...brief,recipeId:recipe.id});
  const instrumental=recipe.vocals==='Instrumental';
  return normalizeBrief({...brief,recipeId:recipe.id,idea:brief.idea.trim()?brief.idea:recipe.summary,
    bpm:recipe.bpm,vocals:recipe.vocals,withLyrics:!instrumental,
    advanced:{enabled:true,key:'',scale:'',chords:'',groove:recipe.groove,arrangement:recipe.arc,
      instruments:recipe.palette.map(([instrument,character])=>({instrument,sound:'',character,moment:''}))},
    lyricDirection:{...brief.lyricDirection,energy:'Contrastes',delivery:recipe.lyricCraft,structure:recipe.structure.join(' → '),voiceA:'',voiceB:'',interaction:recipe.vocals.startsWith('Dúo')?'Alternar estrofas y compartir el estribillo.':''},
    sections:recipe.structure.map((label,index)=>({id:crypto.randomUUID(),label,energy:/chorus|drop|reprise/i.test(label)?7:index===0?3:5,
      voice:instrumental||/^(intro|outro|build|breakdown|interlude)$/i.test(label)?'Sin voz':'Según dirección vocal',delivery:'',instruments:'',notes:'',reference:''})),
  });
}
